import assert from "node:assert/strict";
import { selectInline } from "../src/inline.js";
import type { ModelFinding } from "../src/types.js";

const f = (severity: ModelFinding["severity"], category: string, known = false): ModelFinding =>
  ({ path: "frontend/src/a.ts", line: 3, severity, category, known, body: "..." });
const findings = [f("high", "correctness"), f("low", "style"), f("medium", "naming"), f("medium", "correctness", true), f("high", "security")];
const quietCategories = new Set(["naming", "security"]);

test("on a person's PR every finding is posted", () => {
  assert.equal(selectInline(findings, { agentPr: false, quietCategories }).inline.length, 5);
});
test("on Nova's PR only new high and medium findings are posted", () => {
  const { inline, counted } = selectInline(findings, { agentPr: true, quietCategories });
  assert.deepEqual(inline.map((x) => x.category), ["correctness", "security"]);
  assert.deepEqual(counted, { known: { high: 0, medium: 1, low: 0 }, minor: { high: 0, medium: 0, low: 1 }, quiet: { high: 0, medium: 1, low: 0 } });
});

