import test from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { applyVerdict, citeHolds } from "../src/skeptic.js";

const ws = mkdtempSync(join(tmpdir(), "ws-"));
mkdirSync(join(ws, "src"));
writeFileSync(join(ws, "src/a.ts"), "const a = 1;\nexport const b = a + 1;\n");
const finding = { file: "src/a.ts", line: 2, severity: "high" as const, confidence: "high" as const, title: "b is off by one" };

test("a cite inside the file holds", () => assert.equal(citeHolds("src/a.ts:2", ws), true));
test("a cite past the end or outside the checkout does not", () => {
  assert.equal(citeHolds("src/a.ts:40", ws), false);
  assert.equal(citeHolds("../etc/passwd:1", ws), false);
});
test("refuted findings are dropped", () => {
  assert.equal(applyVerdict(finding, { verdict: "refuted", cite: "src/a.ts:1", reason: "a is 1" }), undefined);
});
